def record_existing_links(apps, schema_editor):
    card_model = apps.get_model('hr_app', 'OnboardingCard')
    link_model = apps.get_model('hr_app', 'OnboardingEmployeeLink')

    def display_name(profile):
        if profile is None:
            return ''
        user = profile.user
        return (f'{user.first_name} {user.last_name}'.strip() or user.username)[:320]

    cards = card_model.objects.filter(employee__isnull=False).select_related(
        'employee__profile__user', 'created_by__user'
    )
    for card in cards.iterator():
        link = link_model.objects.create(
            card_id=card.id,
            employee_id=card.employee_id,
            employee_no=card.employee.employee_no,
            employee_name=display_name(card.employee.profile),
            actor_id=card.created_by_id,
            actor_name=display_name(card.created_by),
        )
        link_model.objects.filter(pk=link.pk).update(created_at=card.created_at)


